export function cx(...parts: (string | false | null | undefined)[]): string {
  return parts.filter(Boolean).join(' ')
}

export const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n))

export const pct = (x: number, digits = 1) => `${(x * 100).toFixed(digits)}%`

export function formatHours(h: number): string {
  return h < 1 ? `${Math.round(h * 60)}m` : `${h.toFixed(1)}h`
}

export function formatWhen(iso: string): string {
  const d = new Date(iso)
  return Number.isNaN(d.getTime()) ? iso : d.toISOString().replace('T', ' ').slice(0, 16) + 'Z'
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { countUp } from './theatre'

/**
 * Motion for the existing components. Three rules keep it honest:
 * - Nothing animates on first paint. A number starts at its value, so server-rendered markup reads the same as the page.
 * - A change animates from the value on screen to the new one, so a figure never jumps to zero and back.
 * - Reduced motion turns every animation off, and the final value is shown at once.
 */

export const reduceMotion = (): boolean =>
  typeof window !== 'undefined' && typeof window.matchMedia === 'function' && window.matchMedia('(prefers-reduced-motion: reduce)').matches

/** Eases a number from its current value to `target` when `target` changes. Returns the value to show. */
export function useCountUp(target: number, duration = 700): number {
  const [value, setValue] = useState(target)
  const shown = useRef(target)
  useEffect(() => {
    const from = shown.current
    if (from === target) return
    if (reduceMotion()) { shown.current = target; setValue(target); return }
    const start = performance.now()
    let raf = 0
    const tick = (now: number) => {
      const k = Math.min(1, (now - start) / duration)
      const v = from + countUp(target - from, k)
      shown.current = k < 1 ? v : target
      setValue(shown.current)
      if (k < 1) raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [target, duration])
  return value
}


/** A figure that eases to a new value when it changes. Renders the final value on first paint. Props are plain data, so a server component can pass them. */
export function Count({ value, digits = 0, prefix = '', suffix = '' }: { value: number; digits?: number; prefix?: string; suffix?: string }) {
  const v = useCountUp(Number.isFinite(value) ? value : 0)
  if (!Number.isFinite(value)) return <>{prefix}{String(value)}{suffix}</>
  return <>{prefix}{v.toLocaleString('en-US', { maximumFractionDigits: digits })}{suffix}</>
}

import type { CSSProperties } from 'react'

// Rules for playing a run back one step at a time. The point of each: the playhead is always a real step, the time
// left is the sum of the steps still to come, and the callout points at a value the run actually produced.

export type Stage = {
  id: string
  title: string
  /** What the step says while it plays. Shown as the caption, one word at a time. */
  detail?: string
  /** What the step needed before it could run. */
  inputs?: string[]
  /** What it produced. */
  result?: string
  /** How long the step takes, in minutes. Used for the time left. */
  minutes?: number
  /** Where the loupe points on the stage, as shares of its width and height (0 to 1), and the value it shows. */
  focus?: { x: number; y: number; label: string }
}

export type StageState = 'done' | 'current' | 'todo'

/** Keeps an index on a real step. An empty run has index 0 and nothing to show. */
export function clampIndex(i: number, n: number): number {
  if (n <= 0) return 0
  const v = Number.isFinite(i) ? Math.round(i) : 0
  return Math.min(n - 1, Math.max(0, v))
}

const mins = (s: Stage) => (Number.isFinite(s.minutes) ? Math.max(0, s.minutes!) : 0)

/** Minutes of the steps from the playhead to the end, including the one playing. */
export function minutesLeft(stages: Stage[], index: number): number {
  return stages.slice(clampIndex(index, stages.length)).reduce((n, s) => n + mins(s), 0)
}

/** Minutes of the steps before the playhead. */
export function minutesDone(stages: Stage[], index: number): number {
  return stages.slice(0, clampIndex(index, stages.length)).reduce((n, s) => n + mins(s), 0)
}

export const stateOf = (index: number, i: number): StageState => (i < index ? 'done' : i === index ? 'current' : 'todo')

/**
 * Where the loupe circle sits: beside the point it magnifies, on the side with room, and kept fully inside the stage. The
 * leader line runs from the point to the circle's centre.
 */
export function loupeAt(focus: { x: number; y: number }, box: { w: number; h: number }, radius: number): { cx: number; cy: number; tipX: number; tipY: number; r: number } {
  const r = Math.max(24, radius)
  const w = Math.max(1, box.w)
  const h = Math.max(1, box.h)
  const fx = Math.min(1, Math.max(0, Number.isFinite(focus.x) ? focus.x : 0.5))
  const fy = Math.min(1, Math.max(0, Number.isFinite(focus.y) ? focus.y : 0.5))
  const tipX = fx * w
  const tipY = fy * h
  const side = fx < 0.5 ? 1 : -1
  const cx = Math.min(w - r, Math.max(r, tipX + side * r * 1.7))
  const cy = Math.min(h - r, Math.max(r, tipY - r * 0.6))
  return { cx, cy, tipX, tipY, r }
}

/** Eases a count from 0 to `target` over `t` in 0 to 1, fast at first and slowing down. */
export function countUp(target: number, t: number): number {
  const k = Math.min(1, Math.max(0, Number.isFinite(t) ? t : 1))
  return target * (1 - Math.pow(1 - k, 3))
}

/** Per-item timing for the `.ol-in` and `.ol-grow` entrances: item `i` starts `i` steps after the first. */
export const after = (i: number): CSSProperties => ({ ['--i' as string]: i })

/** How a unit reads next to a number: a symbol before it for money, the unit after it for anything else. */
export function unitAffix(unit: string): { prefix: string; suffix: string } {
  const sym = ({ USD: '$', GBP: '£', EUR: '€' } as Record<string, string>)[unit]
  return sym ? { prefix: sym, suffix: '' } : { prefix: '', suffix: ` ${unit}` }
}

'use client'

import { useEffect, useState } from 'react'
import { clampIndex } from './theatre'
import { reduceMotion } from './motion'

/**
 * Shared playhead for components that can replay themselves one step at a time. The index is always a real step,
 * nothing plays unless asked, and reduced motion still steps but never autoplays.
 */
export function usePlayback(count: number, { intervalMs = 1600, start = 0, param }: { intervalMs?: number; start?: number; param?: string } = {}) {
  const [index, setIndex] = useState(start)
  const [playing, setPlaying] = useState(false)
  const at = clampIndex(index, count)
  const last = count > 0 && at === count - 1

  // Deep link: ?param=3 opens on the third step, and moving the playhead keeps the address current. Read after mount so server markup matches.
  useEffect(() => {
    if (!param) return
    const n = Number(new URLSearchParams(window.location.search).get(param))
    if (Number.isInteger(n) && n >= 1) setIndex(n - 1)
  }, [param])
  useEffect(() => {
    if (!param || count === 0) return
    const url = new URL(window.location.href)
    if (url.searchParams.get(param) === String(at + 1)) return
    url.searchParams.set(param, String(at + 1))
    window.history.replaceState(null, '', url)
  }, [param, at, count])

  useEffect(() => {
    if (!playing) return
    if (last || reduceMotion()) { setPlaying(false); return }
    const t = setTimeout(() => setIndex(at + 1), intervalMs)
    return () => clearTimeout(t)
  }, [playing, at, last, intervalMs])

  return {
    at,
    last,
    playing,
    set: (i: number) => setIndex(clampIndex(i, count)),
    toggle: () => { if (last) setIndex(0); setPlaying((p) => !p || last) },
  }
}

export type PlaybackState = ReturnType<typeof usePlayback>

/** Play, back, next and a scrubber. Arrow keys and space work while the bar has focus. */
export function PlaybackBar({ pb, count, label }: { pb: PlaybackState; count: number; label: string }) {
  return (
    <div
      className="ol-playbar"
      role="toolbar"
      aria-label={`${label} playback`}
      onKeyDown={(e) => {
        if (e.key === 'ArrowRight') { pb.set(pb.at + 1); e.preventDefault() }
        else if (e.key === 'ArrowLeft') { pb.set(pb.at - 1); e.preventDefault() }
      }}
    >
      <button type="button" className="ol-btn" onClick={() => pb.set(pb.at - 1)} disabled={pb.at === 0}>Back</button>
      <button type="button" className="ol-btn" onClick={pb.toggle} aria-pressed={pb.playing}>{pb.playing ? 'Pause' : pb.last ? 'Replay' : 'Play'}</button>
      <button type="button" className="ol-btn" onClick={() => pb.set(pb.at + 1)} disabled={pb.last}>Next</button>
      <input className="ol-scrub" type="range" min={0} max={Math.max(0, count - 1)} value={pb.at} onChange={(e) => pb.set(Number(e.target.value))} aria-label={`${label} position`} />
      <span className="ol-sub ol-mono">{count === 0 ? 0 : pb.at + 1} / {count}</span>
    </div>
  )
}

import type { ReactNode } from 'react'
import { cx } from './util'

/**
 * Where a piece of generated UI is in its life, so a component can be placed before its data is whole.
 * `loading`: nothing yet, show a skeleton of the same height. `partial`: some data has arrived, show it and mark the
 * rest as still coming. `awaiting`: all of it is here and a person has to act before anything goes on. `ready`: all of it.
 * `error`: it will not arrive. Follows the stages a streamed tool call goes through.
 */
export type Status = 'loading' | 'partial' | 'awaiting' | 'ready' | 'error'

/** What to draw instead of the component while it has nothing to show. Returns null when the component should draw itself. */
export function gateFor(status: Status | undefined, o: { title: string; className?: string; rows?: number; error?: string }): ReactNode | null {
  if (status === 'loading') {
    return (
      <section role="group" className={cx('ol', className(o))} aria-label={o.title} aria-busy="true">
        <h3 className="ol-title">{o.title}</h3>
        <div className="ol-skel" aria-hidden="true">{Array.from({ length: o.rows ?? 3 }, (_, i) => <span key={i} className="ol-skelrow" />)}</div>
        <p className="ol-sub">Loading</p>
      </section>
    )
  }
  if (status === 'error') {
    return (
      <section role="group" className={cx('ol', className(o))} aria-label={o.title}>
        <h3 className="ol-title">{o.title}</h3>
        <p className="ol-text-bad" role="alert">{o.error ?? 'This could not be loaded.'}</p>
      </section>
    )
  }
  return null
}

const className = (o: { className?: string }) => o.className

/** A trailing row that says more is on the way, or that a person has to act. Rendered only while a component is partial or awaiting. */
export function pendingRow(status: Status | undefined): ReactNode {
  if (status === 'partial') return <p className="ol-sub ol-pending" role="status">More is on the way</p>
  if (status === 'awaiting') return <p className="ol-sub ol-pending" role="status">Waiting for a person to decide</p>
  return null
}

export type FieldStatus = 'streaming' | 'complete'

/**
 * Which fields of a streaming object are still being written, in the way assistant-ui's `propStatus` and Hashbrown's parser
 * nodes report it. Without a parser this is an approximation: a model writes keys in order, so while the object is open the
 * last key present is the one still arriving and the keys before it are done. Once the object is complete, every key is.
 */
export function propStatus(args: Record<string, unknown> | undefined, argsComplete: boolean): { argsStatus: FieldStatus; propStatus: Record<string, FieldStatus> } {
  const keys = Object.keys(args ?? {})
  const last = keys[keys.length - 1]
  return {
    argsStatus: argsComplete ? 'complete' : 'streaming',
    propStatus: Object.fromEntries(keys.map((k) => [k, !argsComplete && k === last ? 'streaming' : 'complete'])) as Record<string, FieldStatus>,
  }
}

/**
 * Reads the JSON a model has written so far. Streamed text stops anywhere, so an open string, array or object is closed
 * at the end and the value is whatever is known now. `complete` is true only when the text parses as it stands. A key that
 * has been written but has no value yet is dropped, because a value that has not started is not a value.
 */
export function parsePartial(text: string): { value: unknown; complete: boolean } {
  try { return { value: JSON.parse(text), complete: true } } catch { /* fall through to repair */ }
  const stack: string[] = []
  let inString = false
  let escaped = false
  for (const ch of text) {
    if (inString) { if (escaped) escaped = false; else if (ch === '\\') escaped = true; else if (ch === '"') inString = false; continue }
    if (ch === '"') inString = true
    else if (ch === '{') stack.push('}')
    else if (ch === '[') stack.push(']')
    else if (ch === '}' || ch === ']') stack.pop()
  }
  let out = inString ? (escaped ? text.slice(0, -1) : text) + '"' : text
  // Take off a dangling comma, colon, or key that has no value yet, then close what is open.
  for (let i = 0; i < 4; i++) {
    const t = out.replace(/\s+$/, '')
    if (/,$/.test(t)) out = t.slice(0, -1)
    else if (/:$/.test(t)) out = t.slice(0, -1).replace(/"(?:[^"\\]|\\.)*"\s*$/, '').replace(/,\s*$/, '')
    else if (/[{,]\s*"(?:[^"\\]|\\.)*"$/.test(t) && stack[stack.length - 1] === '}') out = t.replace(/"(?:[^"\\]|\\.)*"$/, '').replace(/,\s*$/, '')
    else break
  }
  try { return { value: JSON.parse(out + stack.reverse().join('')), complete: false } } catch { return { value: undefined, complete: false } }
}

/**
 * What a person did in a component, in one shape whatever the host. A model hears about it through one of the adapters:
 * as a tool result in the AI SDK, or as context in an MCP App. The decision itself is already bound to the plan hash.
 */
export type OrluneAction = { name: string; context: Record<string, unknown> }

/** `viewHash` is the hash of what the reviewer was shown when they decided, from `viewDigest`. */
export const decisionAction = (id: string, decision: string, planHash: string, message?: string, viewHash?: string, viewReceipt?: string): OrluneAction => ({
  name: 'decision',
  context: { id, decision, planHash, ...(message ? { message } : {}), ...(viewHash ? { viewHash } : {}), ...(viewReceipt ? { viewReceipt } : {}) },
})

export const inputAction = (result: { action: 'accept' | 'decline' | 'cancel'; content?: Record<string, unknown> }): OrluneAction => ({
  name: 'input',
  context: { action: result.action, ...(result.content ? { content: result.content } : {}) },
})

/** The `output` for the AI SDK's `addToolOutput({ tool, toolCallId, output })`. */
export const toToolOutput = (a: OrluneAction): { action: string } & Record<string, unknown> => ({ action: a.name, ...a.context })

/** The argument for an MCP App's `app.updateModelContext(...)`: a text block the model reads on its next turn. */
export const toModelContext = (a: OrluneAction): { content: { type: 'text'; text: string }[] } => ({
  content: [{ type: 'text', text: `The person did "${a.name}": ${JSON.stringify(a.context)}` }],
})

/**
 * The action as an A2UI v0.9 client-to-server message, in the shape A2UI's actions guide documents: `version` and an
 * `action` with `name`, `surfaceId`, `sourceComponentId`, `timestamp` and `context`. Send it over whatever transport your
 * A2UI agent uses.
 */
export const toA2uiAction = (a: OrluneAction, o: { surfaceId: string; sourceComponentId: string; at?: Date }) => ({
  version: 'v0.9' as const,
  action: { name: a.name, surfaceId: o.surfaceId, sourceComponentId: o.sourceComponentId, timestamp: (o.at ?? new Date()).toISOString(), context: a.context },
})

/**
 * What the model wrote that did not fit, as an A2UI v0.9 `VALIDATION_FAILED` error, which is how A2UI tells an agent to
 * correct its output and send the UI again. Pair it with `onInvalid` from the OpenUI binding.
 */
export const toA2uiError = (invalid: { component: string; issues: { path: string; message: string }[] }, o: { surfaceId: string }) => ({
  version: 'v0.9' as const,
  error: {
    code: 'VALIDATION_FAILED' as const,
    surfaceId: o.surfaceId,
    path: `/${invalid.component}${invalid.issues[0]?.path ? `/${invalid.issues[0].path}` : ''}`,
    message: invalid.issues.map((i) => `${i.path || 'value'}: ${i.message}`).join('; ') || `${invalid.component} did not fit its schema.`,
  },
})

/** The AI SDK tool-part states, as the `status` a component takes. A request for approval is `awaiting`: everything is shown and a person has to act. */
export type ToolPartState = 'input-streaming' | 'input-available' | 'approval-requested' | 'approval-responded' | 'output-available' | 'output-error' | 'output-denied'

export const statusOfToolPart = (state: ToolPartState): 'loading' | 'partial' | 'awaiting' | 'ready' | 'error' => {
  switch (state) {
    case 'input-streaming': return 'partial'
    case 'approval-requested': return 'awaiting'
    case 'input-available': return 'loading'
    case 'output-error':
    case 'output-denied': return 'error'
    default: return 'ready'
  }
}

// Small scale and format helpers shared by the chart-like components. No dependencies.

export type Scale = ((v: number) => number) & { invert: (px: number) => number; domain: [number, number]; range: [number, number] }

export function linear(domain: [number, number], range: [number, number]): Scale {
  const [d0, d1] = domain
  const [r0, r1] = range
  const span = d1 - d0 || 1
  const f = ((v: number) => r0 + ((v - d0) / span) * (r1 - r0)) as Scale
  f.invert = (px: number) => d0 + ((px - r0) / (r1 - r0 || 1)) * span
  f.domain = domain
  f.range = range
  return f
}

/** Round tick values that fit in [min, max], about `count` of them (1, 2, 5 times a power of ten). */
export function niceTicks(min: number, max: number, count = 6): number[] {
  if (!(max > min)) return [min]
  const raw = (max - min) / Math.max(count, 1)
  const pow = Math.pow(10, Math.floor(Math.log10(raw)))
  const err = raw / pow
  const step = (err >= 7.5 ? 10 : err >= 3.5 ? 5 : err >= 1.5 ? 2 : 1) * pow
  const out: number[] = []
  for (let v = Math.ceil(min / step) * step; v <= max + step * 1e-9; v += step) out.push(Math.round(v / step) * step)
  return out
}

/** 850 ms, 1.20 s, 2 m 05 s. */
export function formatDuration(ms: number): string {
  if (!Number.isFinite(ms)) return ''
  if (ms === 0) return '0'
  const abs = Math.abs(ms)
  if (abs < 1) return `${(ms * 1000).toFixed(0)} µs`
  if (abs < 1000) return `${Number(ms.toFixed(abs < 10 ? 1 : 0))} ms`
  if (abs < 60_000) return `${(ms / 1000).toFixed(abs < 10_000 ? 2 : 1)} s`
  const sign = ms < 0 ? '-' : ''
  if (abs >= 86_400_000) return `${sign}${Math.floor(abs / 86_400_000)} d ${Math.floor((abs % 86_400_000) / 3_600_000)} h`
  if (abs >= 3_600_000) return `${sign}${Math.floor(abs / 3_600_000)} h ${String(Math.round((abs % 3_600_000) / 60_000)).padStart(2, '0')} m`
  const m = Math.floor(abs / 60_000)
  const s = Math.round((abs % 60_000) / 1000)
  return `${ms < 0 ? '-' : ''}${m} m ${String(s).padStart(2, '0')} s`
}

export const formatCount = (n: number) => new Intl.NumberFormat('en', { notation: n >= 100_000 ? 'compact' : 'standard', maximumFractionDigits: 1 }).format(n)
export const formatUsd = (n: number) => (n < 0.01 && n > 0 ? '<$0.01' : new Intl.NumberFormat('en', { style: 'currency', currency: 'USD' }).format(n))

/** Cycles through the categorical palette defined as --ol-c1..8 in styles.css. */
export const swatch = (i: number) => `var(--ol-c${(((i % 8) + 8) % 8) + 1})`

export const clampNum = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n))

import { useEffect, useRef, useState, type RefObject } from 'react'

/** Width of an element, kept current with ResizeObserver. Returns `initial` on the server and before first measure. */
export function useWidth<T extends HTMLElement>(initial = 720): [RefObject<T | null>, number] {
  const ref = useRef<T | null>(null)
  const [width, setWidth] = useState(initial)
  useEffect(() => {
    const el = ref.current
    if (!el) return
    const measure = () => setWidth(Math.max(240, Math.round(el.getBoundingClientRect().width)))
    measure()
    if (typeof ResizeObserver === 'undefined') return
    const ro = new ResizeObserver(measure)
    ro.observe(el)
    return () => ro.disconnect()
  }, [])
  return [ref, width]
}

/** Copies text and reports success briefly. Safe when the clipboard is unavailable. */
export function useCopy(): [boolean, (text: string) => void] {
  const [done, setDone] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  useEffect(() => () => clearTimeout(timer.current), [])
  return [
    done,
    (text) => {
      navigator.clipboard?.writeText(text).then(() => {
        setDone(true)
        clearTimeout(timer.current)
        timer.current = setTimeout(() => setDone(false), 1400)
      }, () => undefined)
    },
  ]
}

/** Small inline marks, so no component depends on emoji or symbol fonts. They inherit the current colour. */
const base = { width: 14, height: 14, viewBox: '0 0 14 14', fill: 'none', stroke: 'currentColor', strokeWidth: 1.8, strokeLinecap: 'round', strokeLinejoin: 'round', 'aria-hidden': true, focusable: false } as const

export const Check = () => <svg {...base} className="ol-icon"><path d="M2.5 7.5 5.6 10.5 11.5 3.8" /></svg>
export const Cross = () => <svg {...base} className="ol-icon"><path d="M3.5 3.5 10.5 10.5M10.5 3.5 3.5 10.5" /></svg>
export const Lock = ({ open }: { open?: boolean }) => (
  <svg {...base} className="ol-icon"><rect x="2.6" y="6.2" width="8.8" height="6" rx="1.4" />{open ? <path d="M4.6 6.2V4.4a2.4 2.4 0 0 1 4.6-.9" /> : <path d="M4.6 6.2V4.4a2.4 2.4 0 0 1 4.8 0v1.8" />}</svg>
)
export const Fit = () => <svg {...base} className="ol-icon"><path d="M2 5V2h3M9 2h3v3M12 9v3H9M5 12H2V9" /></svg>

export type Guarantee = {
  id: string
  statement: string
  check: string
  deadlineHours?: number
  remedy: string
}

export type Manifest = {
  schema?: string
  engagement: string
  created?: string
  /** Role to party name, for example { provider: 'acme', client: 'client' }. Both must sign. */
  parties?: Record<string, string>
  guarantees: Guarantee[]
}

export type SignatureFile = {
  schema?: string
  manifestSha256: string
  signatures: Record<string, { signedAt: string; sig: string }>
}

export type LedgerEvent = {
  seq: number
  type: string
  at: string
  by: string
  prev: string
  sig: string
  label?: string
  ref?: number
  result?: string
  guarantee?: string
  [extra: string]: unknown
}

/** Everything needed to verify a record with no network: the files plus each party's public key (PEM, SPKI). */
export type RecordBundle = {
  manifest: Manifest
  signatures: SignatureFile
  ledger: LedgerEvent[]
  publicKeys: Record<string, string>
}

export type GuaranteeStatus = 'honored' | 'pending' | 'breached' | 'remedied'

export type GuaranteeResult = {
  id: string
  status: GuaranteeStatus
  detail: string
  /** True when a guarantee was breached and no remedy event exists. */
  remedyOutstanding: boolean
}

export type VerifiedEvent = {
  seq: number
  type: string
  at: string
  by: string
  label?: string
  result?: string
  ref?: number
  guarantee?: string
  /** First 12 hex characters of this event's hash, which the next event chains to. */
  hash: string
  signatureValid: boolean
  chainValid: boolean
}

export type VerifyResult = {
  ok: boolean
  engagement: string
  manifestSha256: string
  signatures: {
    party: string
    valid: boolean
    signedAt?: string
    /** A short fingerprint of the key that signed, so a reader can tell which key it was. */
    keyId?: string
    /** Whether that key is on the list you passed in `trustedKeys`. Absent when you passed none. */
    trusted?: boolean
  }[]
  /**
   * `trusted`: every signing key is on your list. `valid-unknown-signer`: the signatures check but a key is not on it.
   * `not-checked`: you gave no list, so only validity was checked. Any trusted record is also valid.
   */
  trust?: 'trusted' | 'valid-unknown-signer' | 'not-checked'
  ledger: { events: number; intact: boolean }
  guarantees: GuaranteeResult[]
  events: VerifiedEvent[]
  problems: string[]
  verifiedAt: string
}

// Exact binomial machinery in log space, stable for n in the thousands. Ported from the failure calculus
// so a client statistician can audit it in one file.

const logFactCache: number[] = [0, 0]
function logFact(n: number): number {
  for (let i = logFactCache.length; i <= n; i++) logFactCache[i] = (logFactCache[i - 1] ?? 0) + Math.log(i)
  return logFactCache[n] ?? 0
}
const logChoose = (n: number, k: number) => logFact(n) - logFact(k) - logFact(n - k)

function binomPmf(k: number, n: number, p: number): number {
  if (p <= 0) return k === 0 ? 1 : 0
  if (p >= 1) return k === n ? 1 : 0
  return Math.exp(logChoose(n, k) + k * Math.log(p) + (n - k) * Math.log(1 - p))
}
function binomCdf(k: number, n: number, p: number): number {
  let s = 0
  for (let i = 0; i <= k; i++) s += binomPmf(i, n, p)
  return Math.min(1, s)
}
const binomTailGE = (k: number, n: number, p: number) => (k <= 0 ? 1 : 1 - binomCdf(k - 1, n, p))

export type Interval = { lower: number; upper: number }

/** Clopper-Pearson exact interval for passes out of n, found by bisection on the binomial CDF. */
export function clopperPearson(passes: number, n: number, confidence = 0.95): Interval {
  if (!Number.isInteger(n) || n < 1) throw new RangeError('n must be a positive integer')
  if (!Number.isInteger(passes) || passes < 0 || passes > n) throw new RangeError('passes must be an integer from 0 to n')
  const alpha = 1 - confidence
  const bisect = (isLow: (p: number) => boolean) => {
    let lo = 0
    let hi = 1
    for (let i = 0; i < 100; i++) {
      const mid = (lo + hi) / 2
      if (isLow(mid)) lo = mid
      else hi = mid
    }
    return (lo + hi) / 2
  }
  const lower = passes === 0 ? 0 : bisect((p) => binomTailGE(passes, n, p) <= alpha / 2)
  const upper = passes === n ? 1 : bisect((p) => binomCdf(passes, n, p) > alpha / 2)
  return { lower, upper }
}

/** Upper bound on the true failure rate when zero failures were seen in n cases: 1 - alpha^(1/n). */
export function zeroFailureUpperBound(n: number, confidence = 0.95): number {
  if (!Number.isInteger(n) || n < 1) throw new RangeError('n must be a positive integer')
  return 1 - Math.pow(1 - confidence, 1 / n)
}

/**
 * Exact McNemar p-value (two-sided) for a paired re-test on the same case set. Under no change, the cases
 * that flipped split Binomial(regressed + improved, 0.5).
 */
export function mcnemarExact(regressed: number, improved: number): number {
  if (![regressed, improved].every((x) => Number.isInteger(x) && x >= 0)) throw new RangeError('counts must be non-negative integers')
  const n = regressed + improved
  if (n === 0) return 1
  return Math.min(1, 2 * binomCdf(Math.min(regressed, improved), n, 0.5))
}

/* orlune: plain CSS, no Tailwind. Theme by overriding the --ol-* variables, or inherit a shadcn theme:
   --background, --foreground, --muted-foreground, --border and --primary are read when present. */
.ol {
  --ol-bg: var(--background, #ffffff);
  --ol-fg: var(--foreground, #16181d);
  --ol-muted: var(--muted-foreground, #5d6470);
  --ol-line: var(--border, #e3e5ea);
  --ol-accent: var(--primary, #1d232b);
  --ol-surface: color-mix(in srgb, var(--ol-fg) 4%, var(--ol-bg));
  --ol-good: #1b7249;
  --ol-warn: #8f4f00;
  --ol-bad: #b3261e;
  --ol-radius: 10px;
  --ol-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--ol-fg);
  background: var(--ol-bg);
  border: 1px solid var(--ol-line);
  border-radius: var(--ol-radius);
  padding: 16px;
  font: 14px/1.45 system-ui, -apple-system, 'Segoe UI', sans-serif;
  box-sizing: border-box;
  container: ol / inline-size;
}
/* Dark theme: follows the OS unless data-theme says otherwise. The host's shadcn variables win when present;
   the fallbacks keep every pair readable when the host defines none. */
