.ol-evtype { font-weight: 600; }
.ol-track { position: relative; height: 12px; border-radius: 8px; background: var(--ol-surface); border: 1px solid var(--ol-line); margin: 10px 0 6px; }
.ol-band { position: absolute; top: 0; bottom: 0; background: color-mix(in srgb, var(--ol-accent) 30%, transparent); border-radius: 8px; }
