.ol-table tr[data-flip='improved'] > th { background: color-mix(in srgb, var(--ol-good) 10%, transparent); }
.ol-compare-bar { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; margin: 12px 0 8px; }

